/* eslint-disable no-undef */
import { Component, Element, Event, EventEmitter, h, Host, Prop } from '@stencil/core';
import { MarginTypes } from '../../types';
import { handleAutofocus } from '../../utils/autofocus';

@Component({
  tag: 'groupui-grid',
  styleUrl: 'grid.scss',
  shadow: true,
})
export class Grid {
  /**
   * sets the grid type (fixed or fluid)
   */
  @Prop({ reflect: true }) readonly type: 'fixed' | 'fluid';

  /**
   * custom gutter size of the column for every breakpoint. (specific gutter definitions overwrite this)
   */
  @Prop({ reflect: true }) readonly gutter: string;

  /**
   * custom gutter size of the column for breakpoint xs (css like e.g. 5px 10px 5px 10px)
   */
  @Prop({ reflect: true }) readonly gutterXs: string;

  /**
   * custom gutter size of the column for breakpoint s (css like e.g. 5px 10px 5px 10px)
   */
  @Prop({ reflect: true }) readonly gutterS: string;

  /**
   * custom gutter size of the column for breakpoint m (css like e.g. 5px 10px 5px 10px)
   */
  @Prop({ reflect: true }) readonly gutterM: string;

  /**
   * custom gutter size of the column for breakpoint l (css like e.g. 5px 10px 5px 10px)
   */
  @Prop({ reflect: true }) readonly gutterL: string;

  /**
   * custom gutter size of the column for breakpoint xl (css like e.g. 5px 10px 5px 10px)
   */
  @Prop({ reflect: true }) readonly gutterXl: string;

  /**
   * custom gutter size of the column for breakpoint xxl (css like e.g. 5px 10px 5px 10px)
   */
  @Prop({ reflect: true }) readonly gutterXxl: string;

  /**
   * choose between flexible and static margins
   */
  @Prop({ reflect: true }) readonly marginType: MarginTypes = 'static';

  /**
   * custom margin size of the column for every breakpoint. (specific margin definitions overwrite this)
   */
  @Prop({ reflect: true }) readonly margin: string;

  /**
   * custom margin size of the column for breakpoint s (applicable only to marginType = 'custom')
   */
  @Prop({ reflect: true }) readonly marginS: string;

  /**
   * custom margin size of the column for breakpoint m (applicable only to marginType = 'custom')
   */
  @Prop({ reflect: true }) readonly marginM: string;

  /**
   * custom margin size of the column for breakpoint l (applicable only to marginType = 'custom')
   */
  @Prop({ reflect: true }) readonly marginL: string;

  /**
   * custom margin size of the column for breakpoint xl (applicable only to marginType = 'custom')
   */
  @Prop({ reflect: true }) readonly marginXl: string;

  /**
   * custom margin size of the column for breakpoint xxl (applicable only to marginType = 'custom')
   */
  @Prop({ reflect: true }) readonly marginXxl: string;

  /**
   * dispatched when component finished loading
   */
  @Event({ bubbles: false }) groupuiDidLoad: EventEmitter<void>;

  @Element() host: HTMLElement;

  private gridRowAddedObserver: MutationObserver;

  private GRID_ROW_NODE_NAME = 'GROUPUI-GRID-ROW';

  componentWillLoad() {
    this.propagateGridProperties();
  }

  private propagateGridProperties() {
    this.gutter && this.gridRowsWithoutProperty('gutter').forEach((it) => (it.gutter = this.gutter));
    this.gutterXs && this.gridRowsWithoutProperty('gutter-xs').forEach((it) => (it.gutterXs = this.gutterXs));
    this.gutterS && this.gridRowsWithoutProperty('gutter-s').forEach((it) => (it.gutterS = this.gutterS));
    this.gutterM && this.gridRowsWithoutProperty('gutter-m').forEach((it) => (it.gutterM = this.gutterM));
    this.gutterL && this.gridRowsWithoutProperty('gutter-l').forEach((it) => (it.gutterL = this.gutterL));
    this.gutterXl && this.gridRowsWithoutProperty('gutter-xl').forEach((it) => (it.gutterXl = this.gutterXl));
    this.gutterXxl && this.gridRowsWithoutProperty('gutter-xxl').forEach((it) => (it.gutterXxl = this.gutterXxl));

    this.margin && this.gridRowsWithoutProperty('margin').forEach((it) => (it.margin = this.margin));
    this.marginS && this.gridRowsWithoutProperty('margin-s').forEach((it) => (it.marginS = this.marginS));
    this.marginM && this.gridRowsWithoutProperty('margin-m').forEach((it) => (it.marginM = this.marginM));
    this.marginL && this.gridRowsWithoutProperty('margin-l').forEach((it) => (it.marginL = this.marginL));
    this.marginXl && this.gridRowsWithoutProperty('margin-xl').forEach((it) => (it.marginXl = this.marginXl));
    this.marginXxl && this.gridRowsWithoutProperty('margin-xxl').forEach((it) => (it.marginXxl = this.marginXxl));

    this.marginType && this.gridRowsWithoutProperty('margin-type').forEach((it) => (it.marginType = this.marginType));

    this.type && this.gridRowsWithoutProperty('type').forEach((it) => (it.type = this.type));
  }

  componentDidLoad() {
    this.gridRowAddedObserver = new MutationObserver(this.callback);
    this.gridRowAddedObserver.observe(this.host, { childList: true });
    this.groupuiDidLoad.emit();
    handleAutofocus(this.host);
  }

  private callback = (mutationList) => {
    for (const mutation of mutationList) {
      if (mutation.type === 'childList' && this.nodeListIncludesGridRow(mutation.addedNodes)) {
        this.propagateGridProperties();
      }
    }
  };

  private nodeListIncludesGridRow(nodeList) {
    return Array.from(nodeList)
      .map((node: Node) => node.nodeName)
      .includes(this.GRID_ROW_NODE_NAME);
  }

  private gridRowsWithoutProperty(attribute: string): HTMLGroupuiGridRowElement[] {
    return Array.from(this.host.querySelectorAll('groupui-grid-row')).filter((row) => !row.getAttribute(attribute));
  }

  disconnectedCallback() {
    // When using conditional rendering (like *ngIf in Angular), the observer might already be removed.
    // That's why we need to check if it is still there before disconnecting.
    if (this.isGridRowMutationObserverStillPresent()) {
      this.gridRowAddedObserver.disconnect();
    }
  }

  private isGridRowMutationObserverStillPresent(): boolean {
    return this.gridRowAddedObserver !== undefined;
  }

  render() {
    return (
      <Host>
        <slot></slot>
      </Host>
    );
  }
}
